parameters.jsCode:
// Contract guard: whatever the agent produced, the webhook only ever returns
// an object that satisfies agentResponseSchema in lib/n8n/types.ts.
const FALLBACK = {
  status: 'question',
  message: 'Sorry, I lost my train of thought for a second. Could you tell me once more which repetitive task you would most like to hand off?'
};

function str(value, max) {
  if (value === null || value === undefined) return '';
  return String(value).replace(/\s+/g, ' ').trim().slice(0, max);
}

function strList(value, max) {
  if (!Array.isArray(value)) return [];
  return value.map(function (v) { return str(v, max); }).filter(function (v) { return v.length > 0; });
}

function unwrap(raw) {
  let value = raw;
  for (let i = 0; i < 3; i += 1) {
    if (typeof value === 'string') {
      const text = value.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { value = JSON.parse(text); } catch (e) { return null; }
      continue;
    }
    if (value && typeof value === 'object' && !value.status && value.output !== undefined) {
      value = value.output;
      continue;
    }
    break;
  }
  return value && typeof value === 'object' ? value : null;
}

function cleanBlueprint(b) {
  if (!b || typeof b !== 'object') return null;
  const kinds = ['deterministic', 'ai', 'human'];
  const steps = (Array.isArray(b.steps) ? b.steps : []).slice(0, 8).map(function (s) {
    const kind = s && kinds.indexOf(s.kind) !== -1 ? s.kind : 'deterministic';
    return { title: str(s && s.title, 80), description: str(s && s.description, 400), kind: kind };
  }).filter(function (s) { return s.title && s.description; });
  const integrations = (Array.isArray(b.integrations) ? b.integrations : []).map(function (i) {
    return { name: str(i && i.name, 60), role: str(i && i.role, 200) };
  }).filter(function (i) { return i.name && i.role; });
  let hours = b.estimatedHoursSavedPerWeek;
  if (typeof hours === 'string' && hours.trim() !== '') hours = Number(hours);
  hours = typeof hours === 'number' && isFinite(hours) ? Math.min(80, Math.max(0, hours)) : null;
  const out = {
    name: str(b.name, 120),
    problem: str(b.problem, 600),
    trigger: str(b.trigger, 200),
    inputs: strList(b.inputs, 200),
    steps: steps,
    integrations: integrations,
    exceptions: strList(b.exceptions, 300),
    outputs: strList(b.outputs, 200),
    complexity: ['beginner', 'intermediate', 'advanced'].indexOf(b.complexity) !== -1 ? b.complexity : 'intermediate',
    difficulty: ['easy', 'moderate', 'hard'].indexOf(b.difficulty) !== -1 ? b.difficulty : 'moderate',
    estimatedHoursSavedPerWeek: hours,
    assumptions: strList(b.assumptions, 300)
  };
  if (!out.name || !out.problem || !out.trigger) return null;
  if (out.inputs.length < 1 || out.steps.length < 2 || out.integrations.length < 1 || out.outputs.length < 1) return null;
  return out;
}

const item = $input.first().json;
const candidate = item.error ? null : unwrap(item.output !== undefined ? item.output : item);
let response = FALLBACK;

if (candidate && (candidate.status === 'question' || candidate.status === 'blueprint')) {
  const message = str(candidate.message, 2000);
  if (candidate.status === 'blueprint') {
    const blueprint = cleanBlueprint(candidate.blueprint);
    if (blueprint) {
      response = { status: 'blueprint', message: message || 'Here is your automation blueprint.', blueprint: blueprint };
    }
  } else if (message) {
    response = { status: 'question', message: message };
    const replies = (Array.isArray(candidate.quickReplies) ? candidate.quickReplies : []).map(function (q) {
      return { label: str(q && q.label, 60), value: str(q && (q.value || q.label), 200) };
    }).filter(function (q) { return q.label && q.value; }).slice(0, 6);
    if (replies.length) response.quickReplies = replies;
  }
}

return [{ json: response }];

const SHARED_SECRET = '<TTA_SECRET>';
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
const fail = function (statusCode, error) { return [{ json: { valid: false, statusCode: statusCode, error: error } }]; };

const suppliedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'];
if (suppliedSecret !== SHARED_SECRET) {
  return fail(403, 'Forbidden.');
}

if (!body || typeof body !== 'object') {
  return fail(400, 'Invalid request body.');
}

const action = body.action;
if (action !== 'send-blueprint' && action !== 'build-request') {
  return fail(400, 'Invalid action.');
}

const firstName = String(body.firstName || '').trim().replace(/[\r\n]+/g, ' ');
const email = String(body.email || '').trim().toLowerCase();
const blueprintName = String(body.blueprintName || (body.blueprint && body.blueprint.name) || '').trim().replace(/[\r\n]+/g, ' ');
const blueprintMarkdown = String(body.blueprintMarkdown || '').trim();

if (!firstName || firstName.length > 80) {
  return fail(400, 'Invalid first name.');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 200) {
  return fail(400, 'Invalid email.');
}
if (!blueprintName || blueprintName.length > 120 || blueprintMarkdown.length < 20 || blueprintMarkdown.length > 30000) {
  return fail(400, 'Complete blueprint content is required.');
}
if (typeof body.blueprintHtml !== 'string' || body.blueprintHtml.length < 50) {
  return fail(400, 'Complete blueprint content is required.');
}

const cardId = String((body.session && body.session.cardId) || 'unknown');
const capturedAt = String(body.capturedAt || new Date().toISOString());
const ownerEmail = 'you@example.com';
const recipient = action === 'send-blueprint' ? email : ownerEmail;
const subject = action === 'send-blueprint'
  ? 'Your automation blueprint: ' + blueprintName
  : 'Tap to Automate build request — ' + firstName;
const message = action === 'send-blueprint'
  ? 'Hi ' + firstName + ',\n\nHere is the automation blueprint you requested from Tap to Automate.\n\n' + blueprintMarkdown + '\n\nCard: ' + cardId + '\nRequested: ' + capturedAt + '\n\nReply to this email if you would like help building it.'
  : 'Action: Build request\nName: ' + firstName + '\nEmail: ' + email + '\nBlueprint: ' + blueprintName + '\nCard: ' + cardId + '\nCaptured: ' + capturedAt + '\n\n' + blueprintMarkdown;

return [{ json: {
  valid: true,
  statusCode: 200,
  action: action,
  firstName: firstName,
  email: email,
  blueprintName: blueprintName,
  blueprintMarkdown: blueprintMarkdown,
  ownerEmail: ownerEmail,
  recipient: recipient,
  subject: subject,
  message: message,
  cardId: cardId,
  capturedAt: capturedAt
} }];

const item = $input.first();
const webhookInput = $('Lead Webhook').first().json;
const body = webhookInput.body || {};
const workflowJson = String(body.workflowJson || '').trim();
let workflowFilename = String(body.workflowFilename || 'automation-n8n-workflow.json')
  .trim()
  .replace(/[^a-z0-9._-]+/gi, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 120) || 'automation-n8n-workflow.json';
if (!workflowFilename.toLowerCase().endsWith('.json')) workflowFilename += '.json';

if (workflowJson.length < 100 || workflowJson.length > 200000) {
  return [{ json: { valid: false, statusCode: 400, error: 'Complete n8n workflow JSON is required.' } }];
}

let parsedWorkflow;
try {
  parsedWorkflow = JSON.parse(workflowJson);
} catch (e) {
  return [{ json: { valid: false, statusCode: 400, error: 'Workflow attachment is not valid JSON.' } }];
}

if (!parsedWorkflow || typeof parsedWorkflow !== 'object' || parsedWorkflow.active !== false || !Array.isArray(parsedWorkflow.nodes) || parsedWorkflow.nodes.length < 2 || !parsedWorkflow.connections || typeof parsedWorkflow.connections !== 'object') {
  return [{ json: { valid: false, statusCode: 400, error: 'Workflow attachment is not an importable inactive n8n workflow.' } }];
}

const workflowBase64 = Buffer.from(workflowJson, 'utf8').toString('base64');
const attachmentNote = '\n\nAttached: ' + workflowFilename + '\nImport it into n8n, add your own credentials, review each field marked SETUP, test it, and only then activate it.';

return [{
  json: Object.assign({}, item.json, {
    valid: true,
    workflowBase64: workflowBase64,
    workflowFilename: workflowFilename,
    subject: item.json.action === 'send-blueprint'
      ? 'Your automation blueprint + n8n workflow: ' + item.json.blueprintName
      : item.json.subject,
    message: item.json.message + attachmentNote
  })
}];
